import { useCallback, useEffect, useId, useMemo, useRef, useState } from "react";
import { useLocation } from "react-router-dom";
import { useQueryClient } from "@tanstack/react-query";
import Box from "@mui/material/Box";
import Alert from "@mui/material/Alert";
import Button from "@mui/material/Button";
import Collapse from "@mui/material/Collapse";
import IconButton from "@mui/material/IconButton";
import Paper from "@mui/material/Paper";
import Typography from "@mui/material/Typography";
import AutoAwesomeIcon from "@mui/icons-material/AutoAwesome";
import CloseIcon from "@mui/icons-material/Close";
import ExpandMoreIcon from "@mui/icons-material/ExpandMore";
import CodeMirror from "@uiw/react-codemirror";
import { useShallow } from "zustand/react/shallow";
import { parseAsString, useQueryState, useQueryStates } from "nuqs";
import { EditorView } from "@codemirror/view";

import { useDashboardEditorStore } from "../store/useDashboardEditorStore";
import { useConnectionStore } from "../store/useConnectionStore";
import { useThemeStore } from "../store/useThemeStore";
import { useSearchPanelUIStore } from "../store/useSearchPanelUIStore";
import { useExplorerStore } from "../store/useExplorerStore";
import { ElasticsearchClient, buildExplorerQuery, isDimensionField } from "../services/es";
import type { FieldInfo, ExplorerFilter } from "../services/es";
import type { EsqlResponse } from "../types";
import { useExploreFields } from "../hooks/useExploreFields";
import { useExploreQuery } from "../hooks/useExploreQuery";
import { useGlobalCollapseShortcut } from "../hooks/useGlobalCollapseShortcut";
import { INSIGHT_GUARDRAIL } from "../hooks/insightPromptUtils";
import { usePageSlotInsights } from "../hooks/usePageSlotInsights";
import { formatEsqlQuery } from "../services/es/queryText";

import QueryAnnotationOverlay, { useQueryExplanation } from "./QueryAnnotationOverlay";
import { createEsqlQueryEditorExtensions } from "./queryEditorExtensions";
import { InsightSlotProvider } from "./InsightSlotContext";
import InsightSlot from "./InsightSlot";
import MetricsSearchPanel from "./explore/MetricsSearchPanel";
import NamespaceLanding from "./explore/NamespaceLanding";
import ExploreContentArea from "./explore/ExploreContentArea";
import { useExplorerUrlSync } from "./explore/useExplorerUrlSync";
import {
  encodeFilters,
  explorerSearchParsers,
  exploreSearchUrlKeys,
  isHiddenDimensionField,
  metricNamespaceOf,
} from "./explore/exploreUtils";
import { EXPLORE_INSIGHT_SLOT_IDS, EXPLORE_INSIGHT_SLOTS } from "./explore/exploreInsightSlots";

const EXPLORE_SYSTEM_PROMPT =
  "You are a metrics observability assistant." +
  " Analyse the current metric exploration context and produce per-slot insights." +
  " When the explore-content slot shows an ungrouped metric chart, suggest the most useful dimension to group by from the available dimensionFields. " +
  " Include suggestedDimension with the exact field name (e.g. host.name) so the UI can offer a one-click Apply. " +
  " Prefer dimensions that split the metric meaningfully (e.g. host.name for system metrics, service.name for app metrics)." +
  INSIGHT_GUARDRAIL;

function normalizeCommittedRawQuery(rawQuery: string | null): string | null {
  return rawQuery?.trim() ? rawQuery : null;
}

export default function ExplorePage() {
  const queryClient = useQueryClient();
  const [selectedNamespace, setSelectedNamespace] = useState<string | null>(null);
  const [dismissedError, setDismissedError] = useState<string | null>(null);
  const { timeRange, setTimeRange } = useDashboardEditorStore(
    useShallow((s) => ({
      timeRange: s.dashboard.timeRange,
      setTimeRange: s.setTimeRange,
    })),
  );
  const connection = useConnectionStore((s) => s.connection);
  const themeMode = useThemeStore((s) => s.themeMode);
  const metricsSearchCollapsed = useSearchPanelUIStore((s) => s.metricsSearchCollapsed);
  const setMetricsSearchCollapsed = useSearchPanelUIStore((s) => s.setMetricsSearchCollapsed);

  const location = useLocation();
  const [urlState, setUrlState] = useQueryStates(explorerSearchParsers, {
    urlKeys: exploreSearchUrlKeys,
    history: "push",
  });
  const [urlFilters, setUrlFilters] = useQueryState(
    "filters",
    parseAsString.withOptions({ history: "push" }),
  );
  const [initialSearch] = useState(() => location.search);
  const [initialUrlState] = useState(() => urlState);
  const [initialUrlFilters] = useState(() => urlFilters);

  const {
    indexPattern,
    selectedMetric,
    metricType,
    aggregation,
    filters,
    groupBy,
    rawQuery,
    setIndexPattern,
    setSelectedMetric,
    setAggregation,
    addFilter,
    removeFilter,
    clearFilters,
    setGroupBy,
    setRawQuery,
  } = useExplorerStore(
    useShallow((s) => ({
      indexPattern: s.indexPattern,
      selectedMetric: s.selectedMetric,
      metricType: s.metricType,
      aggregation: s.aggregation,
      filters: s.filters,
      groupBy: s.groupBy,
      rawQuery: s.rawQuery,
      setIndexPattern: s.setIndexPattern,
      setSelectedMetric: s.setSelectedMetric,
      setAggregation: s.setAggregation,
      addFilter: s.addFilter,
      removeFilter: s.removeFilter,
      clearFilters: s.clearFilters,
      setGroupBy: s.setGroupBy,
      setRawQuery: s.setRawQuery,
    })),
  );

  useExplorerUrlSync({
    initialSearch,
    initialUrlFilters: initialUrlFilters,
    initialUrlState,
    indexPattern,
    selectedMetric,
    aggregation,
    filters,
    groupBy,
    timeRange,
    setIndexPattern,
    setSelectedMetric,
    setSelectedNamespace,
    setAggregation,
    addFilter,
    clearFilters,
    setGroupBy,
    setTimeRange,
    setUrlState,
    setUrlFilters,
  });

  const { fields, fieldsLoading } = useExploreFields(indexPattern);
  const [, setQueryContextView] = useState<EditorView | null>(null);
  const [metricsQueryEditorCollapsed, setMetricsQueryEditorCollapsed] = useState(true);
  const [metricsEditorFocused, setMetricsEditorFocused] = useState(false);
  const [metricsExplainOpen, setMetricsExplainOpen] = useState(false);
  const metricsExplainPanelId = useId();

  const client = useMemo(
    () => (connection ? new ElasticsearchClient(connection) : null),
    [connection],
  );

  const selectedMetricNamespace = useMemo(() => {
    if (!selectedMetric) return null;
    return metricNamespaceOf(selectedMetric);
  }, [selectedMetric]);

  const selectedMetricField = useMemo(
    () => fields.find((field) => field.name === selectedMetric) ?? null,
    [fields, selectedMetric],
  );

  const [skipDimensionOverview, setSkipDimensionOverview] = useState(false);

  // True when a metric is set (e.g. via URL) but does not exist in the loaded field list.
  const metricNotFound = selectedMetric !== null && !fieldsLoading && selectedMetricField === null;

  const showLanding = !selectedNamespace && !selectedMetric;
  // Show namespace overview when a namespace is picked but no single metric is selected.
  const showOverview = selectedNamespace !== null && !selectedMetric;
  // Show dimension overview when a metric is selected but no groupBy is set yet.
  const showDimensionOverview =
    selectedMetric !== null && !groupBy && !skipDimensionOverview && !metricNotFound;

  // Reconcile metric type after field metadata loads (important for URL hydration paths).
  useEffect(() => {
    if (!selectedMetricField) return;
    const nextMetricType = selectedMetricField.metricType === "counter" ? "counter" : "gauge";
    if (nextMetricType !== metricType) {
      setSelectedMetric(selectedMetricField.name, nextMetricType);
    }
  }, [selectedMetricField, metricType, setSelectedMetric]);

  // Committed override: only updates when the user explicitly triggers Search.
  // This decouples editor keystrokes from the query key so typing does not
  // fire network requests until the user clicks "Search Metrics" or presses
  // Cmd/Ctrl+Enter.
  const [committedRawQuery, setCommittedRawQuery] = useState(() =>
    normalizeCommittedRawQuery(rawQuery),
  );
  const pendingSearchRef = useRef(false);

  // Sync committedRawQuery when rawQuery is programmatically cleared (e.g.
  // navigating away, metric change, or auto-clear when rawQuery matches the
  // generated query).
  useEffect(() => {
    if (rawQuery === null) {
      setCommittedRawQuery(null);
    }
  }, [rawQuery]);

  // Run query via React Query when metric/aggregation/filters/groupBy/timeRange change
  const queryResult = useExploreQuery({
    indexPattern,
    selectedMetric,
    metricType,
    aggregation,
    filters,
    groupBy,
    timeRange,
    enabled: Boolean(
      connection &&
      selectedMetric &&
      indexPattern &&
      !showDimensionOverview &&
      !metricNotFound &&
      !fieldsLoading,
    ),
    queryOverride: committedRawQuery,
  });

  const handleSearch = useCallback(() => {
    const nextCommittedRawQuery = normalizeCommittedRawQuery(rawQuery);
    if (nextCommittedRawQuery === committedRawQuery) {
      void queryClient.invalidateQueries({ queryKey: ["explore-query", connection?.url] });
      return;
    }
    pendingSearchRef.current = true;
    setCommittedRawQuery(nextCommittedRawQuery);
  }, [committedRawQuery, queryClient, connection?.url, rawQuery]);

  useEffect(() => {
    if (!pendingSearchRef.current) return;
    pendingSearchRef.current = false;
    void queryClient.invalidateQueries({ queryKey: ["explore-query", connection?.url] });
  }, [committedRawQuery, queryClient, connection?.url]);

  // Query editor extensions for the CodeMirror editor — ref keeps the
  // closure fresh without recreating the extension array on every render.
  const handleRunQueryRef = useRef<() => void>(() => undefined);
  // eslint-disable-next-line react-hooks/refs
  handleRunQueryRef.current = handleSearch;

  const queryEditorExtensions = useMemo(
    () => [
      EditorView.lineWrapping,
      // eslint-disable-next-line react-hooks/refs
      ...createEsqlQueryEditorExtensions(() => handleRunQueryRef.current()),
    ],
    [],
  );

  const effectiveQuery = useMemo(() => {
    if (!selectedMetric) return "";
    const result = buildExplorerQuery({
      indexPattern,
      metricField: selectedMetric,
      metricType,
      aggregation,
      filters,
      groupBy: groupBy ?? undefined,
      timeRange,
    });
    return result.esql;
  }, [indexPattern, selectedMetric, metricType, aggregation, filters, groupBy, timeRange]);
  const displayQuery = useMemo(() => {
    const raw = rawQuery ?? effectiveQuery;
    if (!raw.trim()) return raw;
    return rawQuery ? raw : formatEsqlQuery(raw);
  }, [rawQuery, effectiveQuery]);

  const metricsQueryEditorExtensions = useMemo(
    () => [
      ...queryEditorExtensions,
      EditorView.contentAttributes.of({ "aria-label": "ES|QL query editor" }),
      EditorView.focusChangeEffect.of((state, focusing) => {
        setMetricsEditorFocused(focusing);
        if (!focusing) {
          const current = state.doc.toString().trim();
          if (current) {
            const formatted = formatEsqlQuery(current);
            if (formatted !== current) {
              setRawQuery(formatted);
            }
          }
        }
        return null;
      }),
    ],
    [queryEditorExtensions, setRawQuery],
  );
  const metricsQueryExplanation = useQueryExplanation(displayQuery);

  useEffect(() => {
    if (!rawQuery) return;
    if (formatEsqlQuery(rawQuery) === formatEsqlQuery(effectiveQuery)) {
      setRawQuery(null);
    }
  }, [effectiveQuery, rawQuery, setRawQuery]);

  // Cmd/Ctrl+[ toggles the search panel collapse
  const toggleMetricsCollapse = useCallback(
    () => setMetricsSearchCollapsed(!useSearchPanelUIStore.getState().metricsSearchCollapsed),
    [setMetricsSearchCollapsed],
  );
  useGlobalCollapseShortcut(toggleMetricsCollapse);

  if (
    dismissedError !== null &&
    (queryResult.status === "loading" || queryResult.status === "success")
  ) {
    setDismissedError(null);
  }

  const handleMetricSelect = useCallback(
    (field: FieldInfo | null) => {
      if (field) {
        const mt = field.metricType === "counter" ? "counter" : "gauge";
        setSelectedMetric(field.name, mt);
        setSelectedNamespace(metricNamespaceOf(field.name));
        setGroupBy(null);
        setSkipDimensionOverview(false);
      } else {
        setSelectedMetric(null);
      }
    },
    [setSelectedMetric, setGroupBy],
  );

  const handleBackToOverview = useCallback(() => {
    setSelectedMetric(null);
    setGroupBy(null);
    setSkipDimensionOverview(false);
  }, [setSelectedMetric, setGroupBy]);

  const handleDimensionSelect = useCallback(
    (dimensionField: string) => {
      setGroupBy(dimensionField);
    },
    [setGroupBy],
  );

  const handleBackToDimensionOverview = useCallback(() => {
    setGroupBy(null);
    setSkipDimensionOverview(false);
  }, [setGroupBy]);

  const handleViewUngrouped = useCallback(() => {
    setSkipDimensionOverview(true);
  }, []);

  const handleAddFilter = useCallback(
    (filter: ExplorerFilter) => {
      addFilter(filter);
    },
    [addFilter],
  );

  const handleBackToNamespaceLanding = useCallback(() => {
    setSelectedMetric(null);
    setSelectedNamespace(null);
    setGroupBy(null);
    setRawQuery(null);
    setSkipDimensionOverview(false);
    // Clear URL-backed metric state immediately so it cannot be re-hydrated.
    void Promise.all([
      setUrlState({ selectedMetric: null, groupBy: null }),
      setUrlFilters(encodeFilters([])),
    ]);
  }, [
    setSelectedMetric,
    setSelectedNamespace,
    setGroupBy,
    setRawQuery,
    setUrlState,
    setUrlFilters,
  ]);

  const chartData: EsqlResponse | null = useMemo(() => {
    if (queryResult.status !== "success" || !queryResult.data) return null;
    return queryResult.data as EsqlResponse;
  }, [queryResult]);

  const dimensionFieldNames = useMemo(() => {
    const base = fields.filter((f) => isDimensionField(f) && !isHiddenDimensionField(f.name));
    if (!selectedMetricNamespace) return base.map((f) => f.name);
    const scoped = base.filter(
      (f) => f.name === selectedMetricNamespace || f.name.startsWith(`${selectedMetricNamespace}.`),
    );
    return (scoped.length > 0 ? scoped : base).map((f) => f.name);
  }, [fields, selectedMetricNamespace]);

  const slotContext = useMemo(
    () =>
      JSON.stringify({
        indexPattern,
        selectedMetric,
        metricType,
        aggregation,
        groupBy,
        filterCount: filters.length,
        dimensionFields: dimensionFieldNames,
        rowCount: chartData?.values.length ?? 0,
        columns: chartData?.columns.map((c) => c.name) ?? [],
        sampleValues: chartData?.values.slice(0, 10) ?? [],
      }),
    [
      indexPattern,
      selectedMetric,
      metricType,
      aggregation,
      groupBy,
      filters.length,
      dimensionFieldNames,
      chartData,
    ],
  );

  const slotInsights = usePageSlotInsights({
    context: slotContext,
    systemPrompt: EXPLORE_SYSTEM_PROMPT,
    cacheKey: `explore-slots::${slotContext}`,
    slots: EXPLORE_INSIGHT_SLOTS,
    enabled: Boolean(selectedMetric && chartData),
  });

  const renderExploreContentActions = useCallback(
    (insight: { suggestedDimension?: string }) => {
      const dim = insight.suggestedDimension?.trim();
      if (!dim || !dimensionFieldNames.includes(dim) || groupBy) return null;
      return (
        <Button
          size="small"
          variant="contained"
          onClick={() => handleDimensionSelect(dim)}
          sx={{ mr: 0.5 }}
        >
          Group by {dim}
        </Button>
      );
    },
    [dimensionFieldNames, groupBy, handleDimensionSelect],
  );

  return (
    <InsightSlotProvider
      summary={slotInsights.summary}
      insights={slotInsights.insights}
      loading={slotInsights.loading}
      error={slotInsights.error}
      refresh={slotInsights.refresh}
    >
      <Box sx={{ display: "flex", flexDirection: "column", gap: 1, height: "100%" }}>
        {showLanding ? (
          <>
            <Paper
              variant="outlined"
              sx={{ display: "flex", flex: 1, flexDirection: "column", overflow: "auto" }}
            >
              <NamespaceLanding
                fields={fields}
                indexPattern={indexPattern}
                onSelectNamespace={(ns) => setSelectedNamespace(ns)}
              />
            </Paper>
          </>
        ) : (
          <>
            <Paper variant="outlined" sx={{ p: 1 }}>
              <Button size="small" variant="text" onClick={handleBackToNamespaceLanding}>
                Back to namespace browser
              </Button>
            </Paper>
            <Box sx={{ width: "100%" }}>
              <InsightSlot slotId={EXPLORE_INSIGHT_SLOT_IDS.exploreSearch}>
                <Box sx={{ width: "100%" }}>
                  <MetricsSearchPanel
                    indexPattern={indexPattern}
                    fields={fields}
                    fieldsLoading={fieldsLoading}
                    selectedMetric={selectedMetric}
                    selectedNamespace={selectedNamespace}
                    metricType={metricType}
                    aggregation={aggregation}
                    filters={filters}
                    groupBy={groupBy}
                    rawQuery={rawQuery}
                    timeRange={timeRange}
                    onIndexPatternChange={setIndexPattern}
                    onNamespaceChange={(namespace) => {
                      setSelectedNamespace(namespace);
                      if (
                        selectedMetric &&
                        namespace &&
                        !selectedMetric.startsWith(`${namespace}.`) &&
                        selectedMetric !== namespace
                      ) {
                        setSelectedMetric(null);
                      }
                    }}
                    onMetricSelect={handleMetricSelect}
                    onAggregationChange={setAggregation}
                    onRemoveFilter={removeFilter}
                    onClearFilters={clearFilters}
                    onGroupByDelete={() => setGroupBy(null)}
                    onRawQueryChange={setRawQuery}
                    onCreateEditor={setQueryContextView}
                    queryEditorExtensions={queryEditorExtensions}
                    themeMode={themeMode}
                    searchLoading={queryResult.status === "loading"}
                    onSearch={handleSearch}
                    searchResultCount={chartData ? chartData.values.length : null}
                    collapsed={metricsSearchCollapsed}
                    onToggleCollapsed={toggleMetricsCollapse}
                  />
                </Box>
              </InsightSlot>
            </Box>

            <Paper variant="outlined" sx={{ p: 1.5 }}>
              <Box
                sx={{
                  display: "flex",
                  gap: 0.5,
                  alignItems: "center",
                  mb: metricsQueryEditorCollapsed ? 0 : 1,
                }}
              >
                <IconButton
                  size="small"
                  onClick={() => setMetricsQueryEditorCollapsed((v) => !v)}
                  aria-expanded={!metricsQueryEditorCollapsed}
                  aria-label={
                    metricsQueryEditorCollapsed
                      ? "Expand ES|QL query section"
                      : "Collapse ES|QL query section"
                  }
                >
                  <ExpandMoreIcon
                    sx={{
                      transform: metricsQueryEditorCollapsed ? "rotate(-90deg)" : "rotate(0deg)",
                      transition: "transform 0.2s",
                      fontSize: 20,
                    }}
                  />
                </IconButton>
                <Typography variant="body2" sx={{ fontWeight: 600 }}>
                  ES|QL Query
                </Typography>
              </Box>

              {metricsQueryEditorCollapsed && (
                <Typography
                  variant="caption"
                  color="text.secondary"
                  noWrap
                  sx={{ display: "block", fontStyle: "italic" }}
                >
                  {metricsQueryExplanation ?? displayQuery}
                </Typography>
              )}

              <Collapse in={!metricsQueryEditorCollapsed} unmountOnExit>
                <Typography
                  variant="caption"
                  color="text.secondary"
                  sx={{ display: "block", mb: 0.5 }}
                >
                  Generated from the metrics picker. Edit before running if needed.
                </Typography>
                <Box
                  sx={{ overflow: "hidden", border: 1, borderColor: "divider", borderRadius: 1 }}
                >
                  <Box sx={{ position: "relative" }}>
                    <CodeMirror
                      value={displayQuery}
                      onChange={(v) => setRawQuery(v)}
                      onCreateEditor={setQueryContextView}
                      extensions={metricsQueryEditorExtensions}
                      theme={themeMode}
                      height="120px"
                      basicSetup={{ lineNumbers: true, foldGutter: false, indentOnInput: false }}
                    />
                    <QueryAnnotationOverlay
                      query={displayQuery}
                      editorFocused={metricsEditorFocused}
                      height={120}
                    />
                    <Box sx={{ position: "absolute", zIndex: 3, right: 8, bottom: 6 }}>
                      <Button
                        size="small"
                        variant="outlined"
                        startIcon={<AutoAwesomeIcon sx={{ fontSize: "14px !important" }} />}
                        onClick={() => setMetricsExplainOpen((v) => !v)}
                        aria-expanded={metricsExplainOpen}
                        aria-controls={metricsExplainPanelId}
                        sx={{
                          minHeight: "unset",
                          py: 0.5,
                          px: 1,
                          opacity: 0.75,
                          lineHeight: 1.4,
                          fontSize: "0.7rem",
                          "&:hover": { opacity: 1 },
                        }}
                      >
                        Explain Query
                      </Button>
                    </Box>
                  </Box>
                  <Collapse in={metricsExplainOpen}>
                    <Box
                      id={metricsExplainPanelId}
                      sx={{
                        py: 1,
                        px: 1.5,
                        borderTop: 1,
                        borderColor: "divider",
                        bgcolor: "action.hover",
                      }}
                    >
                      {metricsQueryExplanation ? (
                        <Typography
                          variant="body2"
                          color="text.secondary"
                          sx={{ fontStyle: "italic" }}
                        >
                          {metricsQueryExplanation}
                        </Typography>
                      ) : (
                        <Typography
                          variant="body2"
                          color="text.disabled"
                          sx={{ fontStyle: "italic" }}
                        >
                          Generating explanation… (requires an AI provider configured in Settings)
                        </Typography>
                      )}
                    </Box>
                  </Collapse>
                </Box>
              </Collapse>
            </Paper>

            {/* Error display */}
            {queryResult.status === "error" &&
              queryResult.error &&
              queryResult.error !== dismissedError && (
                <Alert
                  severity="error"
                  action={
                    <IconButton
                      size="small"
                      aria-label="Dismiss error"
                      onClick={() => setDismissedError(queryResult.error ?? null)}
                    >
                      <CloseIcon fontSize="small" />
                    </IconButton>
                  }
                >
                  {queryResult.error}
                </Alert>
              )}

            <Box sx={{ flex: 1, width: "100%", minHeight: 0 }}>
              <InsightSlot
                slotId={EXPLORE_INSIGHT_SLOT_IDS.exploreContent}
                renderActions={renderExploreContentActions}
              >
                <Box sx={{ width: "100%" }}>
                  <ExploreContentArea
                    fields={fields}
                    client={client}
                    indexPattern={indexPattern}
                    selectedMetric={selectedMetric}
                    selectedMetricNamespace={selectedMetricNamespace}
                    metricType={metricType}
                    aggregation={aggregation}
                    selectedNamespace={selectedNamespace}
                    groupBy={groupBy}
                    showOverview={showOverview}
                    showDimensionOverview={showDimensionOverview}
                    metricNotFound={metricNotFound}
                    chartData={chartData}
                    queryStatus={queryResult.status}
                    timeRange={timeRange}
                    onMetricSelect={handleMetricSelect}
                    onDimensionSelect={handleDimensionSelect}
                    onBackToOverview={handleBackToOverview}
                    onBackToDimensionOverview={handleBackToDimensionOverview}
                    onViewUngrouped={handleViewUngrouped}
                    onAddFilter={handleAddFilter}
                    onSetGroupBy={setGroupBy}
                  />
                </Box>
              </InsightSlot>
            </Box>
          </>
        )}
      </Box>
    </InsightSlotProvider>
  );
}
